def maximal_prefix_sum_sum(n, m):
    MOD = 998244853

    # dp[i][j] will store the number of ways to achieve a prefix sum of j with i elements
    dp = [[0] * (n + m + 1) for _ in range(n + m + 1)]
    dp[0][0] = 1  # Base case: one way to have a prefix sum of 0 with 0 elements

    for i in range(1, n + m + 1):
        for j in range(n + m + 1):
            if j > 0:
                dp[i][j] = dp[i - 1][j - 1]  # Adding a 1
            if j < n + m:
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % MOD  # Adding a -1

    # Calculate the sum of maximal prefix sums
    total_sum = 0
    for i in range(n + m + 1):
        total_sum = (total_sum + dp[n + m][i] * max(0, i)) % MOD

    return total_sum

